 static String get(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setRequestProperty("User-Agent","RotaUnica-Android/0.1 personal navigation");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] a=new byte[8192];int n;while((n=in.read(a))!=-1){out.write(a,0,n);if(out.size()>18000000)throw new IOException("Resposta muito grande");}return out.toString("UTF-8");}finally{c.disconnect();}}
 static String enc(String s){try{return URLEncoder.encode(s,"UTF-8");}catch(Exception e){return s;}}
 static String norm(String s){return Normalizer.normalize(s,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).trim();}
 void voiceSearch(){try{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"pt-BR");startActivityForResult(i,23);}catch(Exception e){toast("Reconhecimento de voz indisponível neste aparelho");}}
 @Override protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(r==23&&c==RESULT_OK&&data!=null){ArrayList<String> a=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(a!=null&&!a.isEmpty()){String s=a.get(0);search.setText(s);if(norm(s).contains("posto"))nearby("fuel");else if(norm(s).contains("restaurante"))nearby("restaurant");else find(s,null);}}}
 void nearby(String kind){if(loc==null){toast("Aguardando GPS");return;}find(kind.equals("fuel")?"posto":"restaurante",kind);}
 void find(String query,String category){if(query.trim().length()<2)return;int token=++searchRequest;Location here=loc;((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);results.removeAllViews();results.addView(text("Buscando no Brasil…",15,false));showResults(true);
 pool.execute(()->{ArrayList<Place> list=new ArrayList<>();try{String q=query.trim();if(q.matches("-?\\d+(\\.\\d+)?\\s*,\\s*-?\\d+(\\.\\d+)?")){String[] a=q.split(",");double lat=Double.parseDouble(a[0].trim()),lon=Double.parseDouble(a[1].trim());if(Math.abs(lat)<=90&&Math.abs(lon)<=180)list.add(new Place("Coordenadas",q,lat,lon));}else{if(q.matches("\\d{5}-?\\d{3}")){JSONObject cep=new JSONObject(get("https://viacep.com.br/ws/"+q.replace("-","")+"/json/"));q=cep.optString("logradouro")+", "+cep.optString("localidade")+", "+cep.optString("uf");}
 String base="https://photon.komoot.io/api/?q="+enc(q)+"&limit=20&countrycode=BR";if(category!=null)base+="&osm_tag="+enc("amenity:"+category);boolean local=here!=null&&(category!=null||!q.contains(","));
 if(local){double x=here.getLongitude(),y=here.getLatitude(),radius=category!=null?.13:.45;try{parsePlaces(get(base+"&lat="+y+"&lon="+x+"&bbox="+(x-radius)+","+(y-radius)+","+(x+radius)+","+(y+radius)),list);}catch(Exception ignored){}}
 if(category==null&&(list.size()<5||!local))parsePlaces(get(base+"&bbox=-74,-34,-34,6"+(here==null?"":"&lat="+here.getLatitude()+"&lon="+here.getLongitude())),list);
 if(local)list.sort(Comparator.comparingDouble(a->a.p.distanceToAsDouble(gp(here))));}
 main.post(()->{if(token==searchRequest)renderResults(list,category);});}catch(Exception e){main.post(()->{if(token==searchRequest){results.removeAllViews();results.addView(text("Busca indisponível. Tente novamente.",15,false));}});}});}
 void parsePlaces(String raw,ArrayList<Place> out)throws Exception{JSONArray fs=new JSONObject(raw).getJSONArray("features");for(int i=0;i<fs.length();i++){JSONObject f=fs.getJSONObject(i),p=f.getJSONObject("properties");if(!"BR".equalsIgnoreCase(p.optString("countrycode")))continue;JSONArray c=f.getJSONObject("geometry").getJSONArray("coordinates");String name=p.optString("name",p.optString("street",p.optString("city","Endereço")));String detail=p.optString("district")+" · "+p.optString("city")+" · "+p.optString("state");Place a=new Place(name,detail,c.getDouble(1),c.getDouble(0));boolean duplicate=false;for(Place b:out)if(norm(a.name).equals(norm(b.name))&&a.p.distanceToAsDouble(b.p)<80)duplicate=true;if(!duplicate)out.add(a);}}
 void showResults(boolean show){ScrollView s=(ScrollView)results.getTag();s.setLayoutParams(new LinearLayout.LayoutParams(-1,show?dp(250):0));}
 void renderResults(ArrayList<Place> list,String category){results.removeAllViews();if(category!=null&&category.equals("fuel"))results.addView(text("Preços por posto ainda não integrados. Distância em linha reta.",12,false));if(list.isEmpty())results.addView(text("Nenhum endereço encontrado.",15,false));for(Place p:list){TextView t=text(p.name+"\n"+p.detail+(loc==null?"":String.format(Locale.US," · %.1f km",p.p.distanceToAsDouble(gp(loc))/1000)),15,false);t.setPadding(dp(12),dp(10),dp(12),dp(10));results.addView(t);t.setOnClickListener(v->{showResults(false);search.setText(p.name);if(adding&&destination!=null){stops.add(p);adding=false;}else{destination=p;stops.clear();driving=false;}calculate();});}}
 void calculate(){if(destination==null||loc==null){toast("Aguardando localização");return;}int token=++request;GeoPoint start=gp(loc);ArrayList<Place> via=new ArrayList<>(stops);Place dest=destination;String profile=mode;summary.setText("Calculando rota…");pool.execute(()->{try{ArrayList<Route> rr=new ArrayList<>();String coords=start.getLongitude()+","+start.getLatitude();for(Place s:via)coords+=";"+s.p.getLongitude()+","+s.p.getLatitude();coords+=";"+dest.p.getLongitude()+","+dest.p.getLatitude();if(profile.equals("bus"))throw new IOException("Ônibus: itinerários ainda indisponíveis");if(profile.equals("moto")){JSONArray points=new JSONArray();points.put(valPoint(start));for(Place s:via)points.put(valPoint(s.p));points.put(valPoint(dest.p));JSONObject payload=new JSONObject().put("locations",points).put("costing","motorcycle").put("units","kilometers").put("language","pt-BR").put("alternates",via.isEmpty()?2:0);JSONObject v=new JSONObject(get("https://valhalla1.openstreetmap.de/route?json="+enc(payload.toString())));rr.add(valRoute(v.getJSONObject("trip")));JSONArray aa=v.optJSONArray("alternates");if(aa!=null)for(int i=0;i<aa.length();i++)rr.add(valRoute(aa.getJSONObject(i).getJSONObject("trip")));}else{JSONArray a=new JSONObject(get("https://routing.openstreetmap.de/routed-"+(profile.equals("walk")?"foot":"car")+"/route/v1/driving/"+coords+"?steps=true&overview=full&geometries=geojson&alternatives=3")).getJSONArray("routes");for(int i=0;i<a.length();i++)rr.add(osRoute(a.getJSONObject(i)));}if(rr.isEmpty())throw new IOException("Nenhuma rota");main.post(()->{if(token!=request)return;origin=start;routes=rr;selected=0;stepIndex=1;drawRoutes();renderRoute();});}catch(Exception e){main.post(()->{if(token==request){routes.clear();summary.setText("Rota indisponível");toast(e.getMessage()==null?"Falha no cálculo":e.getMessage());renderRoute();}});}});}
 JSONObject valPoint(GeoPoint p)throws Exception{return new JSONObject().put("lat",p.getLatitude()).put("lon",p.getLongitude());}
 Route osRoute(JSONObject j)throws Exception{Route r=new Route();r.meters=j.getDouble("distance");r.seconds=j.getDouble("duration");JSONArray a=j.getJSONObject("geometry").getJSONArray("coordinates");for(int i=0;i<a.length();i++)r.points.add(coord(a.getJSONArray(i)));JSONArray legs=j.getJSONArray("legs");for(int i=0;i<legs.length();i++){JSONArray s=legs.getJSONObject(i).getJSONArray("steps");for(int k=0;k<s.length();k++){JSONObject x=s.getJSONObject(k),m=x.getJSONObject("maneuver");String mod=m.optString("modifier");String dir=mod.contains("left")?"à esquerda":mod.contains("right")?"à direita":mod.equals("uturn")?"e faça o retorno":"em frente";String type=m.optString("type");String desc=type.equals("arrive")?"Chegada ao destino":type.equals("depart")?"Inicie o trajeto":type.contains("roundabout")?"Siga pela rotatória":"Siga "+dir;r.steps.add(new Step(coord(m.getJSONArray("location")),desc+" "+x.optString("name")));}}return r;}
 GeoPoint coord(JSONArray a)throws Exception{return new GeoPoint(a.getDouble(1),a.getDouble(0));}
 Route valRoute(JSONObject trip)throws Exception{Route r=new Route();r.meters=trip.getJSONObject("summary").getDouble("length")*1000;r.seconds=trip.getJSONObject("summary").getDouble("time");JSONArray legs=trip.getJSONArray("legs");for(int i=0;i<legs.length();i++){JSONObject l=legs.getJSONObject(i);ArrayList<GeoPoint> line=decode(l.getString("shape"));r.points.addAll(line);JSONArray a=l.getJSONArray("maneuvers");for(int k=0;k<a.length();k++){JSONObject m=a.getJSONObject(k);int index=m.optInt("begin_shape_index");if(index<line.size())r.steps.add(new Step(line.get(index),m.optString("instruction")));}}return r;}
 ArrayList<GeoPoint> decode(String s){ArrayList<GeoPoint> a=new ArrayList<>();int i=0,lat=0,lon=0;while(i<s.length()){int[] v=new int[2];for(int k=0;k<2;k++){int x=0,shift=0,b;do{b=s.charAt(i++)-63;x|=(b&31)<<shift;shift+=5;}while(b>=32);v[k]=(x&1)!=0?~(x>>1):x>>1;}lat+=v[0];lon+=v[1];a.add(new GeoPoint(lat/1e6,lon/1e6));}return a;}
 void drawRoutes(){map.getOverlays().removeAll(routeOverlays);routeOverlays.clear();for(int pass=0;pass<2;pass++)for(int i=0;i<routes.size();i++){if((i==selected)!=(pass==1))continue;final int id=i;Polyline p=new Polyline();p.setPoints(routes.get(i).points);p.getOutlinePaint().setColor(i==selected?BLUE:0xff8197b2);p.getOutlinePaint().setStrokeWidth(dp(i==selected?7:5));p.setOnClickListener((line,m,pos)->{selected=id;stepIndex=1;drawRoutes();renderRoute();return true;});map.getOverlays().add(p);routeOverlays.add(p);}if(destination!=null){Marker m=new Marker(map);m.setPosition(destination.p);m.setTitle(destination.name);map.getOverlays().add(m);routeOverlays.add(m);}if(!driving&&!routes.isEmpty()){ArrayList<GeoPoint> pts=routes.get(selected).points;map.post(()->{try{map.zoomToBoundingBox(org.osmdroid.util.BoundingBox.fromGeoPoints(pts),true,dp(85));}catch(Exception ignored){}});}map.invalidate();}
 void renderRoute(){choices.removeAllViews();if(destination==null)return;LinearLayout modes=new LinearLayout(this);String[] ids={"car","moto","walk","bus"}, names={"Carro","Moto","A pé","Ônibus"};for(int i=0;i<ids.length;i++){String id=ids[i];modes.addView(button((mode.equals(id)?"✓ ":"")+names[i],v->{driving=false;mode=id;calculate();}));}if(!driving)choices.addView(modes);
 if(!routes.isEmpty()){Route r=routes.get(selected);summary.setText(format(r.meters,r.seconds));for(int i=0;i<routes.size();i++){int id=i;Route a=routes.get(i);if(!driving)choices.addView(button((selected==i?"✓ ":"")+"Rota "+(i+1)+" · "+format(a.meters,a.seconds),v->{selected=id;stepIndex=1;drawRoutes();renderRoute();}));}
 LinearLayout actions=new LinearLayout(this);actions.addView(button(driving?"Encerrar":"Iniciar",v->{driving=!driving;warned.clear();stepIndex=1;nav.setVisibility(driving?View.VISIBLE:View.GONE);if(driving){say("Navegação iniciada");progress();}renderRoute();}));actions.addView(button("＋ Parada",v->{adding=true;search.setText("");search.requestFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(search,InputMethodManager.SHOW_IMPLICIT);}));actions.addView(button("Recalcular",v->calculate()));choices.addView(actions);if(driving&&routes.size()>1)choices.addView(button("Trocar rota",v->{selected=(selected+1)%routes.size();stepIndex=1;drawRoutes();renderRoute();}));}
 for(Place p:stops)if(!driving)choices.addView(button("Parada: "+p.name+" ×",v->{stops.remove(p);calculate();}));
 }
 String format(double m,double s){return String.format(Locale.US,"%.1f km · %d min",m/1000,(int)Math.ceil(s/60));}
 void say(String s){if(sound&&voiceReady)tts.speak(s,TextToSpeech.QUEUE_ADD,null,UUID.randomUUID().toString());}
 void alarm(String k,String text){if(!sound)return;if(tone!=null)tone.startTone(k.equals("radar")?ToneGenerator.TONE_CDMA_ALERT_CALL_GUARD:k.equals("lombada")?ToneGenerator.TONE_PROP_BEEP2:ToneGenerator.TONE_PROP_BEEP,260);main.postDelayed(()->say(text),300);}
 static double[] project(GeoPoint p,ArrayList<GeoPoint> line){double total=0,best=Double.MAX_VALUE,along=0,bearing=0;double scale=Math.cos(Math.toRadians(p.getLatitude()));for(int i=1;i<line.size();i++){GeoPoint a=line.get(i-1),b=line.get(i);double dx=(b.getLongitude()-a.getLongitude())*scale,dy=b.getLatitude()-a.getLatitude();double t=Math.max(0,Math.min(1,((p.getLongitude()-a.getLongitude())*scale*dx+(p.getLatitude()-a.getLatitude())*dy)/(dx*dx+dy*dy+1e-20)));double len=a.distanceToAsDouble(b);double dist=p.distanceToAsDouble(new GeoPoint(a.getLatitude()+t*dy,a.getLongitude()+t*(b.getLongitude()-a.getLongitude())));if(dist<best){best=dist;along=total+t*len;bearing=(Math.toDegrees(Math.atan2(dx,dy))+360)%360;}total+=len;}return new double[]{along,best,total,bearing};}
 void progress(){if(loc==null||routes.isEmpty()||destination==null)return;Route r=routes.get(selected);GeoPoint p=gp(loc);double[] pos=project(p,r.points);double remain=Math.max(0,r.meters*(1-pos[0]/Math.max(1,pos[2])));double sec=r.seconds*remain/Math.max(1,r.meters);summary.setText(format(remain,sec)+" · "+new java.text.SimpleDateFormat("HH:mm",new Locale("pt","BR")).format(new Date(System.currentTimeMillis()+(long)(sec*1000))));if(!stops.isEmpty()&&p.distanceToAsDouble(stops.get(0).p)<35){stops.remove(0);say("Parada alcançada");calculate();return;}if(stops.isEmpty()&&p.distanceToAsDouble(destination.p)<25){driving=false;say("Você chegou ao destino");nav.setVisibility(View.GONE);renderRoute();return;}if(pos[1]>100&&System.currentTimeMillis()-lastReroute>30000){lastReroute=System.currentTimeMillis();say("Recalculando rota");calculate();return;}
 while(stepIndex<r.steps.size()-1&&project(r.steps.get(stepIndex).p,r.points)[0]<pos[0]-10)stepIndex++;if(stepIndex<r.steps.size()){Step s=r.steps.get(stepIndex);double d=Math.max(0,project(s.p,r.points)[0]-pos[0]);nav.setText(s.text+" · "+Math.round(d)+" m");if(d<250&&warned.add("step"+stepIndex))say("Em "+Math.round(d)+" metros, "+s.text);}
 if(mode.equals("walk")||pos[1]>65||System.currentTimeMillis()-lastWarn<4500)return;ArrayList<Event> all=new ArrayList<>(fixed);all.addAll(live);Event chosen=null;double nearest=Double.MAX_VALUE;String stage="";for(Event e:all){if(e.expires<System.currentTimeMillis())continue;double max=e.kind.equals("radar")?1000:e.kind.equals("lombada")?220:350;if(p.distanceToAsDouble(e.p)>max+60)continue;double[] v=project(e.p,r.points);double d=v[0]-pos[0];if(v[1]>40||d<0||d>max)continue;if(!Double.isNaN(e.direction)&&Math.abs((v[3]-e.direction+540)%360-180)>65)continue;String k=e.id+(e.kind.equals("radar")?(d>500?":1000":d>250?":500":":250"):":near");if(warned.contains(k))continue;if(d<nearest){chosen=e;nearest=d;stage=k;}}if(chosen!=null){warned.add(stage);lastWarn=System.currentTimeMillis();alarm(chosen.kind,chosen.label+" a "+Math.round(nearest/10)*10+" metros"+(chosen.limit>0?". Limite informado: "+(int)chosen.limit+" quilômetros por hora.":"."));}}
 void settings(){String[] opts={"Sons: "+(sound?"ligados":"desligados"),"Semáforos: tempo ao vivo indisponível","Ônibus: dados pendentes","Preços de combustível: pendentes","Evitar morros e riscos: pendentes","Fontes: OpenStreetMap, Pardal, Waze municipal"};new AlertDialog.Builder(this).setTitle("Configurações e cobertura").setItems(opts,(d,i)->{if(i==0){sound=!sound;if(!sound&&tts!=null)tts.stop();}else toast(opts[i]);}).setPositiveButton("Fechar",null).show();}
 void refresh(){if(loc==null||fetching)return;fetching=true;GeoPoint p=gp(loc);boolean catalog=catalogAt==null||catalogAt.distanceToAsDouble(p)>15000||System.currentTimeMillis()-lastCatalog>21600000;pool.execute(()->{ArrayList<Event> f=new ArrayList<>(),l=new ArrayList<>();boolean ok=false,traffic=false;try{if(catalog){JSONObject states=new JSONObject(get("https://raw.githubusercontent.com/Murkiriel/pardal/main/catalogo.json")).getJSONObject("ufs");Iterator<String> it=states.keys();while(it.hasNext()){String uf=it.next();if(uf.equals("BR"))continue;JSONObject u=states.getJSONObject(uf);JSONArray bb=u.optJSONArray("bbox");if(bb==null||p.getLatitude()<bb.getDouble(0)-.2||p.getLatitude()>bb.getDouble(2)+.2||p.getLongitude()<bb.getDouble(1)-.2||p.getLongitude()>bb.getDouble(3)+.2)continue;try{loadCatalog(uf,p,f);ok=true;}catch(Exception ignored){}}}}catch(Exception ignored){}try{if(p.getLatitude()>-20.5&&p.getLatitude()<-20.1&&p.getLongitude()>-40.6&&p.getLongitude()<-40.1){String base="https://gis.vitoria.es.gov.br/arcgis/rest/services/Opendata/DadosAbertos/MapServer/25/query?where=1%3D1&outFields=uuid%2Calert_type%2Calert_subtype%2Cpubmillis%2Cstreet&outSR=4326&orderByFields=pubmillis%20DESC&resultRecordCount=200&f=json";JSONArray a=new JSONObject(get(base)).getJSONArray("features");for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i),at=x.getJSONObject("attributes"),g=x.getJSONObject("geometry");long stamp=at.optLong("pubmillis");if(stamp<=0||System.currentTimeMillis()-stamp>900000)continue;String type=at.optString("alert_type"),sub=at.optString("alert_subtype");String k=sub.contains("POT_HOLE")?"buraco":type.contains("ACCIDENT")?"acidente":type.contains("CAMERA")?"radar":"perigo";Event e=new Event("waze"+at.optString("uuid"),k,k.equals("radar")?"Fiscalização reportada":k.equals("buraco")?"Buraco reportado":k.equals("acidente")?"Acidente reportado":"Ocorrência reportada","Waze · Prefeitura de Vitória",g.getDouble("y"),g.getDouble("x"));e.expires=stamp+900000;l.add(e);}traffic=!l.isEmpty();}}catch(Exception ignored){}boolean done=ok,tr=traffic;main.post(()->{fetching=false;if(done){fixed=f;catalogAt=p;lastCatalog=System.currentTimeMillis();}live=l;coverage.setText("Mapa OSM · "+fixed.stream().filter(e->e.kind.equals("radar")).count()+" radares · "+(tr?"ocorrências recentes em Vitória":"trânsito ao vivo não confirmado"));drawEvents();});});}
 void loadCatalog(String uf,GeoPoint p,ArrayList<Event> out)throws Exception{String base="https://raw.githubusercontent.com/Murkiriel/pardal/main/estados/"+uf+"/";JSONArray fs=new JSONObject(get(base+"radares.geojson")).getJSONArray("features");for(int i=0;i<fs.length();i++){JSONObject f=fs.getJSONObject(i),a=f.getJSONObject("properties");if(!a.optBoolean("active"))continue;GeoPoint g=coord(f.getJSONObject("geometry").getJSONArray("coordinates"));if(g.distanceToAsDouble(p)>65000)continue;Event e=new Event("radar"+g.getLatitude()+":"+g.getLongitude()+":"+a.optString("direction_deg"),"radar","Atenção, radar","Pardal · "+a.optString("source"),g.getLatitude(),g.getLongitude());e.limit=a.optDouble("limit_kmh",0);e.direction=a.optDouble("direction_deg",Double.NaN);out.add(e);}try{String[] rows=get(base+"lombadas.csv").split("\\r?\\n");for(int i=1;i<rows.length;i++){String[] a=rows[i].split(",");if(a.length<3)continue;double lat=Double.parseDouble(a[0]),lon=Double.parseDouble(a[1]);if(new GeoPoint(lat,lon).distanceToAsDouble(p)>25000)continue;out.add(new Event("bump"+lat+":"+lon,"lombada","Atenção, lombada","Pardal · OSM",lat,lon));}}catch(Exception ignored){}}
 void drawEvents(){map.getOverlays().removeAll(eventOverlays);eventOverlays.clear();ArrayList<Event> all=new ArrayList<>(fixed);all.addAll(live);GeoPoint here=loc==null?null:gp(loc);for(Event e:all){if(here==null||e.p.distanceToAsDouble(here)>12000||e.expires<System.currentTimeMillis())continue;if(eventOverlays.size()>600)break;Marker m=new Marker(map);m.setPosition(e.p);m.setTitle(e.label+(e.limit>0?" · "+(int)e.limit+" km/h":""));m.setSnippet(e.source);GradientDrawable d=bg(e.kind.equals("radar")?0xffc63831:e.kind.equals("lombada")?0xff7e4aa4:0xffe38a24,20);d.setSize(dp(20),dp(20));m.setIcon(d);m.setAnchor(Marker.ANCHOR_CENTER,Marker.ANCHOR_CENTER);map.getOverlays().add(m);eventOverlays.add(m);}map.invalidate();}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
